package ama.transcript;
import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import ama.task.TaskDomainPolicy;import ama.db.TransactionRunner;
/** Read-only actual task-spec declaration, never claims, settles or reconstructs a lease. */
public final class LocalPublicationDeclarationDiagnostic {
 public static void inspect(JdbcTranscriptAuthority authority,TransactionRunner tx,String meeting){var j=new JdbcTemplate(authority.dataSource());j.setQueryTimeout(2);var rows=j.queryForList("SELECT id,task_type,pool,subject_kind,subject_id,producer_key,input_kind,input_id,input_fingerprint,business_version,priority,cancel_epoch,max_attempts FROM durable_task WHERE subject_kind='MEETING' AND subject_id=? AND task_type='KNOWLEDGE_PUBLISH_V1' ORDER BY id LIMIT 2",meeting);if(rows.size()!=1)throw new IllegalArgumentException("One actual publication task required");var spec=TranscriptReadGraph.spec(rows.getFirst());tx.required(()->{authority.publicationDomain().prepare(List.of(spec),TaskDomainPolicy.Acquisition.EXTERNAL_FACT_OBSERVATION,false);return null;});}
 /** Diagnostic only: invokes the read-only recorded source preparation (no lease, claim, provider call or mutation). */
 public static void inspectPrepared(JdbcTranscriptAuthority authority,TransactionRunner tx,JdbcPublicationService service,String meeting){
  var j=new JdbcTemplate(authority.dataSource());j.setQueryTimeout(2);var rows=j.queryForList("SELECT id,task_type,pool,subject_kind,subject_id,producer_key,input_kind,input_id,input_fingerprint,business_version,priority,cancel_epoch,max_attempts FROM durable_task WHERE subject_kind='MEETING' AND subject_id=? AND task_type='KNOWLEDGE_PUBLISH_V1' ORDER BY id LIMIT 2",meeting);if(rows.size()!=1)throw new IllegalArgumentException("One actual publication task required");
  var actor=new ama.contract.IdentityContracts.Actor("dev-owner",ama.contract.IdentityContracts.Status.ACTIVE,Set.of(ama.contract.IdentityContracts.Role.USER));tx.required(()->{authority.savedAccess().require(authority.savedAccess().lock(actor,meeting),ama.access.MeetingAccess.Action.EDIT);return null;});var spec=TranscriptReadGraph.spec(rows.getFirst());var budget=service.limits.ledger(authority.readBudget(),authority.canonicalBudget(),()->false);
  try{var method=JdbcPublicationService.class.getDeclaredMethod("prepareRecorded",String.class,ama.contract.TaskContracts.TaskSpec.class,ama.contract.TaskContracts.TaskLease.class,TranscriptAcquisitionBudget.Ledger.class);method.setAccessible(true);var request=(JdbcPublicationService.Request)method.invoke(service,(String)rows.getFirst().get("id"),spec,null,budget);tx.required(()->{authority.publicationDomain().preparePublicationRequest(spec,request);return null;});}
  catch(java.lang.reflect.InvocationTargetException failure){if(failure.getCause() instanceof RuntimeException cause)throw cause;throw new IllegalStateException("Read-only source preparation unavailable");}catch(ReflectiveOperationException failure){throw new IllegalStateException("Read-only diagnostic unavailable");}
 }

}
